<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { studio, edit, dirty, newProject, openProject, refreshProjects, saveProject, recoverDraft, undoEdit, importGeometry, addScene, reorderScene } from './stores/project-store';
import { api, download } from './services/local-api';
import { retimeProject } from '../../../packages/story-core/src/authoring';
import type { Geometry, ProjectDocument, CameraKeyframe } from '../../../packages/project-schema/src/index';
import ExploreMap from './components/ExploreMap.vue';
import StoryPreview from './components/StoryPreview.vue';
import ImportDialog from './components/ImportDialog.vue';
import ResourcesDialog from './components/ResourcesDialog.vue';
import SceneInspector from './components/SceneInspector.vue';
import RoadwayEditor from './components/RoadwayEditor.vue';
import ResearchPanel from './components/ResearchPanel.vue';
import ExportDialog from './components/ExportDialog.vue';
import WalkshedPanel from './components/WalkshedPanel.vue';
const showResources=ref(false), reviseSourceId=ref('');
const showProjects = ref(false), showImport = ref(false), showExport = ref(false), replacement = ref(''), title = ref('Untitled story'), creating = ref(false), loading = ref(true), inspector = ref('scene'), search = ref('');
const map = ref<InstanceType<typeof ExploreMap>>(), exploreCamera = ref<CameraKeyframe>(), drawing = ref(false), playing = ref(false), jsonEditor = ref(''), showProjectData = ref(false), packageFile = ref<HTMLInputElement>();
const p = computed(() => studio.document!), total = computed(() => p.value?.scenes.reduce((n,s) => n+s.durationFrames,0) ?? 1);
const feature = computed(() => p.value?.features.find(f => f.id === studio.selectedFeatureId)), revision = computed(() => p.value?.featureRevisions.find(r => r.id === feature.value?.currentRevisionId));
const layer = computed(() => { const layers = p.value?.layers.filter(l => l.featureRevisionId === revision.value?.id) ?? []; return layers.find(l => studio.frame >= l.startFrame && studio.frame < l.endFrameExclusive) ?? layers[0]; });
const features = computed(() => p.value?.features.filter(f => f.name.toLowerCase().includes(search.value.toLowerCase())) ?? []);
const sources = computed(() => p.value?.sources.filter(s => revision.value?.sourceIds.includes(s.id)) ?? []);
let animation = 0, startTime = 0, startFrame = 0;
async function action(operation: () => unknown) { studio.error = ''; try { await operation(); } catch(e) { studio.error = String(e); } }
function update(change: (project: ProjectDocument) => void) { void action(() => edit(change)); }
async function create() { creating.value = true; await action(async () => { await newProject(title.value || 'Untitled story'); showProjects.value = false; }); creating.value = false; }
async function open(id: string) { if (dirty() && !window.confirm('Open another project? Your unsaved changes remain in this browser’s recovery copy.')) return; await action(async () => { await openProject(id); showProjects.value = false; }); }
function focusScene(id: string) { playing.value = false; studio.selectedSceneId = id; let offset = 0; for (const s of p.value.scenes) { if (s.id === id) break; offset += s.durationFrames; } studio.frame = offset; }
function focusSelected() { void action(() => { if (!revision.value) throw new Error('Select a feature first.'); addScene(revision.value.geometry, revision.value.id); focusScene(studio.selectedSceneId); inspector.value = 'scene'; }); }
function duplicate() { update(d => { const s = JSON.parse(JSON.stringify(d.scenes.find(s => s.id === studio.selectedSceneId)!)); s.id = crypto.randomUUID(); s.title = (s.title ?? 'Scene') + ' copy'; s.annotations.forEach(a => a.id = crypto.randomUUID()); s.focusSteps?.forEach(step => step.id = crypto.randomUUID()); d.scenes.splice(d.scenes.findIndex(s => s.id === studio.selectedSceneId)+1,0,s); Object.assign(d, retimeProject(d)); }); }
function removeScene() { update(d => { if (d.scenes.length === 1) throw new Error('Keep at least one scene.'); const id = studio.selectedSceneId; const index = d.scenes.findIndex(s => s.id === id); const fallback = d.scenes[index+1]?.id ?? d.scenes[index-1].id; for (const l of d.layers) if (l.sceneRange) { if (l.sceneRange.from === id) l.sceneRange.from = fallback; if (l.sceneRange.through === id) l.sceneRange.through = fallback; } d.scenes.splice(index,1); Object.assign(d,retimeProject(d)); studio.selectedSceneId = fallback; }); focusScene(studio.selectedSceneId); }
async function drawn(geometry: Geometry) { drawing.value = false; await action(async () => { const file = new File([JSON.stringify({ type:'Feature', properties:{name:'Drawn ' + (geometry.type === 'Polygon' ? 'study area' : geometry.type.toLowerCase())}, geometry })],'drawn.geojson',{type:'application/json'}); await importGeometry(file,{ id:crypto.randomUUID(), title:'Author-drawn geometry',sourceKind:'author-origin',interpretation:'editorial',notes:'Manually drawn by the author; verify against a named source before making a factual boundary claim.' }); }); }
function draw(mode: string) { drawing.value = true; map.value?.draw(mode); }
function recordCamera() { update(d => { if (!exploreCamera.value) throw new Error('Move the map to choose a view first.'); const s = d.scenes.find(s => s.id === studio.selectedSceneId)!; s.variantOverrides ??= {}; s.variantOverrides[studio.variant] = { cameraTrack:[JSON.parse(JSON.stringify(exploreCamera.value))] }; }); }
function layerEdit(field: string, value: unknown) { update(d => { const l = d.layers.find(l => l.id === layer.value!.id)!; if (field === 'group') l.group = value as typeof l.group; else if (field === 'from' || field === 'through') { l.sceneRange ??= { from:d.scenes[0].id,through:d.scenes.at(-1)!.id }; l.sceneRange[field] = String(value); Object.assign(d,retimeProject(d)); } else { l.style ??= {stroke:'#177969',fill:'#177969',width:6,fillOpacity:.2,opacity:1}; (l.style as unknown as Record<string,unknown>)[field] = value; } }); }
function trace(enabled: boolean) { update(d => { const l = d.layers.find(l => l.id === layer.value!.id)!; if (!enabled) delete l.trace; else l.trace = {startFrame:l.startFrame,endFrameExclusive:Math.min(l.endFrameExclusive,l.startFrame+60),mode:feature.value?.kind === 'line' ? 'line':'outer-ring'}; }); }
async function importPackage(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; await action(async () => { const response = await fetch('/api/package-import',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-Mutation-Id':crypto.randomUUID()},body:file}); const value = await response.json(); if (!response.ok) throw new Error(value.message); await refreshProjects(); await openProject(value.projectId); if(value.omittedAssets?.length) studio.error = 'This reference package omits ' + value.omittedAssets.length + ' assets. Restore the exact original files before export.'; }); (event.target as HTMLInputElement).value=''; }
function playback() { if(!playing.value)return; studio.frame=Math.min(total.value-1,startFrame+Math.floor((performance.now()-startTime)*.03)); if(studio.frame>=total.value-1){playing.value=false;return;} animation=requestAnimationFrame(playback); }
watch(playing,value=>{cancelAnimationFrame(animation);if(value){if(studio.frame>=total.value-1)studio.frame=0;startFrame=studio.frame;startTime=performance.now();animation=requestAnimationFrame(playback);}});
watch(total,()=>studio.frame=Math.min(studio.frame,total.value-1));
watch(showProjectData,value=>{if(value)jsonEditor.value=JSON.stringify(p.value,null,2);});
function applyProjectData(){update(d=>{const next=JSON.parse(jsonEditor.value);if(next.id!==d.id)throw new Error('Keep the project identity unchanged.');Object.keys(d).forEach(k=>delete (d as unknown as Record<string,unknown>)[k]);Object.assign(d,next);});}
function key(event: KeyboardEvent) { const modifier=event.ctrlKey||event.metaKey;if(modifier && event.key.toLowerCase()==='s'){event.preventDefault();void action(saveProject);}if(modifier && event.key.toLowerCase()==='z' && !['INPUT','TEXTAREA'].includes((event.target as HTMLElement).tagName)){event.preventDefault();undoEdit(event.shiftKey);} }
function beforeUnload(event: BeforeUnloadEvent) { if(dirty()){event.preventDefault();event.returnValue='';} }
onMounted(async()=>{window.addEventListener('keydown',key);window.addEventListener('beforeunload',beforeUnload);await action(async()=>{await refreshProjects();if(studio.projects.length)await openProject(studio.projects[0].id);else showProjects.value=true;});loading.value=false;});
onBeforeUnmount(()=>{cancelAnimationFrame(animation);window.removeEventListener('keydown',key);window.removeEventListener('beforeunload',beforeUnload);});
</script>
<template>
<div class="studio-shell">
<header class="studio-header"><div class="brand"><span class="brand-mark" aria-hidden="true">S</span><div><strong>Storytelling Studio</strong><small>PLACE. EVIDENCE. STORY.</small></div></div><div class="project-heading" v-if="p"><q-input :model-value="p.title" borderless dense aria-label="Project title" @change="e=>update(d=>d.title=e.target.value)" /><span class="save-indicator" role="status">{{ studio.saveState }}</span></div><div class="header-actions"><q-btn flat dense label="Resources" :disable="!p" @click="showResources=true" /><q-btn flat dense label="Projects" @click="showProjects=true" /><q-btn flat dense label="Undo" :disable="!studio.undo.length" @click="undoEdit()" /><q-btn flat dense label="Redo" :disable="!studio.redo.length" @click="undoEdit(true)" /><q-btn outline dense label="Save" :disable="!p" @click="action(saveProject)" /><q-btn color="primary" unelevated label="Export" :disable="!p" @click="showExport=true" /></div></header>
<div v-if="studio.error" class="error-banner" role="alert"><span>{{ studio.error }}</span><q-btn flat dense label="Dismiss" @click="studio.error=''" /></div>
<main v-if="p" class="studio-main"><aside class="library-pane"><div class="pane-heading"><div><span class="eyebrow">Project library</span><h2>Your geography</h2></div><q-btn flat dense label="+ Import" @click="replacement='';reviseSourceId='';showImport=true" /></div><q-input v-model="search" outlined dense placeholder="Find a place or layer" aria-label="Search features" />
<div class="library-list"><button v-for="f in features" :key="f.id" class="feature-row" :class="{selected:studio.selectedFeatureId===f.id}" @click="studio.selectedFeatureId=f.id;map?.fit(f.id)"><span class="feature-symbol">{{ f.kind==='area'?'▱':f.kind==='point'?'●':'⌁' }}</span><span><strong>{{ f.name }}</strong><small>{{ f.kind }} · saved geometry</small></span></button><div v-if="!features.length" class="empty-library"><span class="empty-icon">↗</span><h3>Start with a place</h3><p>Import source geography or draw a study area on the map.</p><q-btn outline label="Import GeoJSON" @click="showImport=true" /></div></div>
<div class="library-footer"><span class="eyebrow">Retained sources</span><div v-for="source in p.sources" :key="source.id" class="source-row"><b>{{ source.title }}</b><small>{{ source.interpretation ?? 'Unclassified' }} · {{ source.sourceKind==='dataset'?source.referencePeriod:'Author origin' }}</small></div><p v-if="!p.sources.length" class="hint">Source records follow the geometry into scenes and exported projects.</p></div></aside>
<section class="workspace"><div class="workspace-toolbar"><q-tabs v-model="studio.workspace" dense align="left" active-color="primary" indicator-color="primary"><q-tab name="explore" label="Explore" /><q-tab name="research" label="Research" /><q-tab name="animate" label="Animate" /></q-tabs><q-btn-toggle v-model="studio.variant" dense flat :options="[{label:'16:9',value:'landscape'},{label:'9:16',value:'portrait'}]" aria-label="Output aspect ratio" /></div>
<div v-if="studio.workspace==='explore'" class="explore-tools"><q-btn flat dense label="Point" @click="draw('Point')" /><q-btn flat dense label="Line" @click="draw('LineString')" /><q-btn flat dense label="Study area" @click="draw('Polygon')" /><q-btn v-if="drawing" color="primary" dense label="Finish drawing" @click="map?.finish()" /><span class="spacer" /><q-btn flat dense label="Use this camera" @click="recordCamera" /><q-btn outline dense label="Create focus scene" :disable="!revision" @click="focusSelected" /></div>
<div class="canvas-stage"><ExploreMap v-if="studio.workspace==='explore'" ref="map" :project="p" :selected="studio.selectedFeatureId" @select="v=>studio.selectedFeatureId=v" @camera="v=>exploreCamera=v" @draw="drawn" /><ResearchPanel v-else-if="studio.workspace==='research'" /><StoryPreview v-else :project="p" :variant="studio.variant" :frame="studio.frame" /></div>
<div v-if="studio.workspace==='animate'" class="transport"><q-btn flat dense :label="playing?'Pause':'Play'" @click="playing=!playing" /><span class="timecode">{{ (studio.frame/30).toFixed(2) }} / {{ (total/30).toFixed(2) }} s</span><q-slider :model-value="studio.frame" :min="0" :max="total-1" :step="1" dense aria-label="Timeline frame" @update:model-value="v=>{playing=false;studio.frame=Number(v)}" /><span class="badge">30 fps</span></div>
<footer class="story-strip"><div class="strip-heading"><span class="eyebrow">Your story · {{ p.scenes.length }} scenes</span><div class="button-row"><q-btn flat dense size="sm" label="+ Scene" @click="action(()=>addScene(revision?.geometry,revision?.id))" /><q-btn flat dense size="sm" label="Duplicate" @click="duplicate" /><q-btn flat dense size="sm" label="Move left" @click="action(()=>reorderScene(studio.selectedSceneId,-1))" /><q-btn flat dense size="sm" label="Move right" @click="action(()=>reorderScene(studio.selectedSceneId,1))" /><q-btn flat dense size="sm" label="Remove" @click="removeScene" /></div></div><div class="scene-cards"><button v-for="(s,i) in p.scenes" :key="s.id" class="scene-card" :class="{selected:studio.selectedSceneId===s.id}" @click="studio.workspace='animate';focusScene(s.id)"><span class="scene-number">{{ String(i+1).padStart(2,'0') }}</span><div class="scene-art" :class="{road:!!s.roadway,research:!!s.researchSnapshotId}"><span>{{ s.roadway?'ROADWAY':s.researchSnapshotId?'EVIDENCE':'MAP' }}</span></div><strong>{{ s.title ?? 'Scene '+(i+1) }}</strong><small>{{ (s.durationFrames/30).toFixed(1) }} seconds</small></button></div></footer>
</section>
<aside class="inspector-pane"><template v-if="studio.workspace==='animate'"><q-tabs v-model="inspector" dense><q-tab name="scene" label="Scene" /><q-tab name="roadway" label="Roadway" /></q-tabs><SceneInspector v-if="inspector==='scene'" :key="studio.selectedSceneId" /><RoadwayEditor v-else /></template>
<div v-else class="inspector-body"><div class="eyebrow">Selected place</div><template v-if="feature && revision"><q-input :model-value="feature.name" outlined dense label="Feature name" @change="e=>update(d=>d.features.find(f=>f.id===feature!.id)!.name=e.target.value)" /><span class="badge">{{ feature.kind }} · revision {{ revision.id.slice(0,8) }}</span><div class="button-row"><q-btn outline dense label="Focus scene" @click="focusSelected" /><q-btn flat dense label="Replace geometry" @click="replacement=feature!.id;reviseSourceId='';showImport=true" /></div>
<template v-if="layer"><h3>Story layer</h3><q-select :model-value="layer.group??'context'" :options="['context','rail','bus','stop','station','service-area','walkshed']" dense outlined label="Layer group" @update:model-value="v=>layerEdit('group',v)" /><div class="form-grid"><label>Line color<input type="color" :value="layer.style?.stroke??'#177969'" @change="e=>layerEdit('stroke',(e.target as HTMLInputElement).value)" /></label><label>Area color<input type="color" :value="layer.style?.fill??'#177969'" @change="e=>layerEdit('fill',(e.target as HTMLInputElement).value)" /></label><q-input :model-value="layer.style?.width??6" type="number" min="0" max="40" dense label="Line width" @change="e=>layerEdit('width',Number(e.target.value))" /><q-input :model-value="layer.style?.fillOpacity??.2" type="number" min="0" max="1" step=".05" dense label="Fill opacity" @change="e=>layerEdit('fillOpacity',Number(e.target.value))" /></div><q-checkbox :model-value="(layer.style?.opacity??1)>0" label="Visible in story" @update:model-value="v=>layerEdit('opacity',v?1:0)" /><q-checkbox v-if="feature.kind!=='point'" :model-value="!!layer.trace" label="Animate a two-second trace" @update:model-value="trace" /><template v-if="layer.trace"><div class="form-grid"><q-input :model-value="layer.trace.startFrame" dense type="number" label="Trace starts (frame)" @change="e=>update(d=>d.layers.find(l=>l.id===layer!.id)!.trace!.startFrame=Number(e.target.value))" /><q-input :model-value="layer.trace.endFrameExclusive" dense type="number" label="Trace ends (frame)" @change="e=>update(d=>d.layers.find(l=>l.id===layer!.id)!.trace!.endFrameExclusive=Number(e.target.value))" /></div></template><q-checkbox v-if="feature.kind==='area'" :model-value="!!layer.fillFade" label="Fade in area fill" @update:model-value="v=>update(d=>{const l=d.layers.find(l=>l.id===layer!.id)!;if(v)l.fillFade={startFrame:l.startFrame,endFrameExclusive:Math.min(l.endFrameExclusive,l.startFrame+30)};else delete l.fillFade;})" /><div v-if="layer.fillFade" class="form-grid"><q-input :model-value="layer.fillFade.startFrame" dense type="number" label="Fill starts (frame)" @change="e=>update(d=>d.layers.find(l=>l.id===layer!.id)!.fillFade!.startFrame=Number(e.target.value))" /><q-input :model-value="layer.fillFade.endFrameExclusive" dense type="number" label="Fill visible (frame)" @change="e=>update(d=>d.layers.find(l=>l.id===layer!.id)!.fillFade!.endFrameExclusive=Number(e.target.value))" /></div><q-select :model-value="layer.sceneRange?.from" :options="p.scenes.map(s=>({label:s.title??s.id,value:s.id}))" emit-value map-options dense outlined label="Keep visible from scene" @update:model-value="v=>layerEdit('from',v)" /><q-select :model-value="layer.sceneRange?.through" :options="p.scenes.map(s=>({label:s.title??s.id,value:s.id}))" emit-value map-options dense outlined label="Keep visible through scene" @update:model-value="v=>layerEdit('through',v)" /></template>
<q-expansion-item label="Source & provenance" default-opened><div v-for="source in sources" :key="source.id" class="section-stack"><b>{{ source.title }}</b><p class="hint">{{ source.notes }}</p><a v-if="source.url" :href="source.url" target="_blank" rel="noreferrer">Open source</a><q-btn v-if="source.sourceKind==='dataset'" flat dense size="sm" label="Revise source evidence" @click="reviseSourceId=source.id;replacement='';showImport=true" /><div class="source-id">Source ID: {{ source.id }}</div><div v-if="source.sourceKind==='dataset'" class="hint">Version {{ source.version??'unknown' }} · period {{ source.referencePeriod??'unknown' }} · publication {{ source.rights.publication }}</div></div></q-expansion-item>
<q-expansion-item v-if="feature.kind==='area'" label="10-minute network walkshed"><WalkshedPanel :key="revision.id" :revision-id="revision.id" /></q-expansion-item>
</template><p v-else class="hint">Select a place in the library to inspect its geometry, appearance, and evidence.</p><q-separator /><q-btn flat dense label="Recover browser draft" @click="action(()=>{if(!recoverDraft())throw new Error('There is no saved browser draft for this project.')})" /><q-btn flat dense label="Download draft JSON" @click="download(JSON.stringify(p,null,2),'story-draft.json','application/json')" /><q-btn flat dense label="Exact project data" @click="showProjectData=true" /></div></aside>
</main><div v-else class="welcome"><div class="eyebrow">Local storytelling tools</div><h1>A clearer story<br>about the places we share.</h1><p>Explore geography. Keep the evidence. Make it move.</p><q-btn color="primary" label="Create your first story" @click="showProjects=true" /><p v-if="loading">Opening local projects…</p></div>
</div>
<q-dialog v-model="showProjects"><q-card class="dialog-card"><q-card-section><div class="eyebrow">Your local workspace</div><h2>Open a story</h2><div class="form-grid"><q-input v-model="title" dense outlined label="New project title" @keyup.enter="create" /><q-btn color="primary" :loading="creating" label="Create project" @click="create" /></div></q-card-section><q-card-section class="project-list"><button v-for="project in studio.projects" :key="project.id" class="project-row" @click="open(project.id)"><b>{{ project.title }}</b><small>{{ new Date(project.updatedAt).toLocaleString() }}</small></button><p v-if="!studio.projects.length">Your projects are saved locally on this computer.</p></q-card-section><q-card-actions><input ref="packageFile" hidden type="file" accept=".gstory" @change="importPackage" /><q-btn outline label="Import .gstory" @click="packageFile?.click()" /><q-space /><q-btn flat label="Close" v-close-popup /></q-card-actions></q-card></q-dialog>
<q-dialog v-model="showImport"><ImportDialog :replace-id="replacement||undefined" :source-id="reviseSourceId||undefined" @done="showImport=false;map?.fit(studio.selectedFeatureId)" /></q-dialog>
<q-dialog v-model="showResources"><ResourcesDialog v-if="showResources" /></q-dialog>
<q-dialog v-model="showExport"><ExportDialog v-if="showExport" /></q-dialog>
<q-dialog v-model="showProjectData"><q-card class="dialog-card"><q-card-section><h2>Exact project data</h2><p>For advanced editing and recovery. Invalid records are rejected. Geometry and source identities already saved cannot be altered in place.</p><q-input v-model="jsonEditor" type="textarea" rows="22" input-class="code-input" outlined /></q-card-section><q-card-actions align="right"><q-btn flat label="Close" v-close-popup /><q-btn color="primary" label="Validate and apply" @click="applyProjectData" /></q-card-actions></q-card></q-dialog>
</template>
